\label{thm:main}
Let $(X,\|\cdot\|_X)$ be a finite-dimensional normed space.  Then, for any $n\geq1$, we have
\begin{equation} \label{eq:main}
\mathsf{c}_X\big(\{-1,1\}^n\big) \gtrsim \sup_{p\in[1,2]} \frac{n}{\mathsf{T}_p(X) \min\{n,\dim(X)\}^{1/p}}
\end{equation}

\label{thm:pisier}
For every $p\in[1,\infty)$ and $\alpha\in(0,1)$, there exist $\mathsf{K}_{p,\alpha}, \mathsf{C}_\alpha\in(0,\infty)$ such that the following holds.  For any normed space $(X,\|\cdot\|_X)$ and any $n\in\mathbb{N}$, every function $f:\{-1,1\}^n\to X$ satisfies
\begin{equation} \label{eq:p1}
\begin{split}
\bigg\| f - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\mu_\alpha^n\bigg\|_{L_p(\log L)^{p/2}(\mu_\alpha^n;X)} \leq \mathsf{K}_{p,\alpha} & \left( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i^\alpha f\Big\|_{L_p(\mu_\alpha^n;X)}^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta)\right)^{1/p}
\\ & + \mathsf{C}_{\alpha}(\log n+1) \int_{\{-1,1\}^n} \Big\|\sum_{i=1}^n\delta_i \partial_i^\alpha f\Big\|_{L_1(\mu_\alpha^n;X)}\,\mathop{}\!\mathrm{d}\sigma_n(\delta).
\end{split}
\end{equation}
If additionally $X$ is assumed to be of finite cotype, then there exists $\mathsf{K}_{p,\alpha}(X)\in(0,\infty)$ such that
\begin{equation} \label{eq:p2}
\bigg\| f - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\mu_\alpha^n\bigg\|_{L_p(\log L)^{p/2}(\mu_\alpha^n;X)} \leq \mathsf{K}_{p,\alpha}(X)  \left( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i^\alpha f\Big\|_{L_p(\mu_\alpha^n;X)}^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta)\right)^{1/p}.
\end{equation}

A metric space $(\mathsf{M},d_\mathsf{M})$ has metric stable type $p\in(0,2)$ with constant $S\in(0,\infty)$ if for any $n\in\mathbb{N}$, every function $f:\{-1,1\}^n\to\mathsf{M}$ satisfies
\begin{equation} \label{eq:st}
\int_{\{-1,1\}^n} d_\mathsf{M}\big( f(x),f(-x)\big)^p \,\mathop{}\!\mathrm{d}\sigma_n(x) \leq S^p  \int_{\{-1,1\}^n} \big\| \big(\mathfrak{d}_1f(x),\ldots,\mathfrak{d}_nf(x)\big)\big\|^p_{\ell_{p,\infty}^n} \,\mathop{}\!\mathrm{d}\sigma_n(x).
\end{equation}

\label{prop:dist}
If a metric space $(\mathsf{M},d_\mathsf{M})$ has metric stable type $p$ with constant $S$, then
\begin{equation} \label{eq:dist}
\forall \ {\bf w}\in\mathbb{R}_+^n,\qquad \mathsf{c}_\mathsf{M}\big(\{-1,1\}^n_{{\bf w}} \big) \geq \frac{\|{\bf w}\|_{\ell_1^n}}{S\|{\bf w}\|_{\ell_{p,\infty}^n}}.
\end{equation}

Due to the product structure of the Markov chain, it suffices to consider the case $n=1$, that is, to prove that for $\alpha\in(0,1)$,
\begin{equation}
\forall \ x,y\in\{-1,1\},\qquad \mu_\alpha(x) p_t^\alpha(x,y) = \mu_\alpha(y) p_t^\alpha(y,x).
\end{equation} 
This follows automatically by the expression \eqref{eq:transition} for the transition matrix. The simple fact that reversibility implies stationarity is well-known \cite[Proposition~1.20]{LLP17}.

Fix $\pmb{\alpha}=(\alpha_1,\ldots,\alpha_n)\in(0,1)^n$ and let $\{P_t^{\pmb{\alpha}}\}_{t\geq0}$ be the semigroup \eqref{eq:sgp}. Then, the action of its generator $\mathscr{L}_{\pmb{\alpha}}$ on a function $f:\{-1,1\}^n\to X$, where $X$ is a vector space, is given by
\begin{equation} \label{eq:gen}
\forall \ x\in\{-1,1\}^n,\qquad \mathscr{L}_{\pmb{\alpha}} f(x) = -\sum_{i=1}^n \partial_i^{\alpha_i} f(x)
\end{equation}
where $\partial_i^\beta f(x) = f(x) - \int_{\{-1,1\}} f(x_1,\ldots,x_{i-1},y,x_{i+1},\ldots,x_n) \, \mathop{}\!\mathrm{d}\mu_\beta(y)$ for $\beta\in(0,1)$.

The claim follows from the expression \eqref{eq:sgp2} of the semigroup and the definition
\begin{equation*}
\forall \ x\in\{-1,1\}^n,\qquad \mathscr{L}_{\pmb{\alpha}} f(x) = \frac{\mathop{}\!\mathrm{d}}{\mathop{}\!\mathrm{d} t}\Big|_{t=0} P_t^{\pmb{\alpha}}f(x). \qedhere
\end{equation*}

Consider the function $g\stackrel{\mathrm{def}}{=} F\circ h_d : \mathbb{S}^d\to\mathbb{R}^d$, where $h_d$ is the function of Lemma \ref{lem:ole}.  By the Borsuk--Ulam theorem and the oddness of $h_d$, there exists a point $w\in\mathbb{S}^d$ such that
\begin{equation}
F(h_d(w)) = g(w) = g(-w) = F(h_d(-w)) = F(-h_d(w))
\end{equation}
and the conclusion follows by choosing $z=h_d(w)\in\mathscr{C}_d^n$.

Fix $t\geq0$ and $\alpha\in(0,1)$. Then,
\begin{equation} \label{eq:center}
\forall \ x\in\{-1,1\},  \  \theta\in \mathbb{R},  \qquad p_t^\alpha(x,1) \eta_t^\alpha(1,x;\theta) + p_t^\alpha(x,-1) \eta_t^\alpha(-1,x;\theta) = 0
\end{equation}
and
\begin{equation} \label{eq:second-mom}
\begin{split}
\min_{\theta\in\mathbb{R}} \max_{x\in\{-1,1\}} \Big\{ p_t^\alpha(x,1)  \eta_t^\alpha(1,x;\theta)^2 & + p_t^\alpha(x,-1)  \eta_t^\alpha(-1,x;\theta)^2 \Big\} \\ & = \frac{e^{-t}}{(e^t-1)(\sqrt{\alpha p_t^\alpha(-1,-1)}+\sqrt{(1-\alpha)p_t^\alpha(1,1)})^2} \leq \frac{1}{e^t-1}.
\end{split}
\end{equation}

The centering condition \eqref{eq:center} can be checked easily using the explicit formulas \eqref{eq:transition} and \eqref{eq:eta} of the matrices. For \eqref{eq:second-mom}, we compute that for any $\theta\in\mathbb{R}$,
\begin{equation}
\begin{split}
 \max_{x\in\{-1,1\}} \Big\{ p_t^\alpha(x,1)  \eta_t^\alpha(1,x;\theta)^2 & + p_t^\alpha(x,-1)  \eta_t^\alpha(-1,x;\theta)^2 \Big\} 
 \\ & = \max\Big\{ \frac{(e^{-t}-\theta)^2}{p_t^\alpha(1,1) p_t^\alpha(1,-1)},  \frac{\theta^2}{p_t^\alpha(-1,1) p_t^\alpha(-1,-1)},\Big\}.
\end{split}
\end{equation}
As this is the maximum of two quadratic functions in $\theta$, its minimum is attained at the point $\theta^\ast$ where they intersect in the interval $(0,e^{-t})$, namely at
\begin{equation}
\theta^\ast = \frac{e^{-t}\sqrt{\alpha p_t^\alpha(-1,-1)}}{\sqrt{\alpha p_t^\alpha(-1,-1)}+\sqrt{(1-\alpha) p_t^\alpha(1,1)}}.
\end{equation}
The first equality in \eqref{eq:second-mom} is immediate, whereas for the inequality we compute
\begin{equation}
\begin{split}
 \frac{e^{-t}}{(e^t-1)(\sqrt{\alpha p_t^\alpha(-1,-1)}+\sqrt{(1-\alpha)p_t^\alpha(1,1)})^2} & \leq \frac{e^{-t}}{(e^t-1)(\alpha p_t^\alpha(-1,-1)+(1-\alpha)p_t^\alpha(1,1))}
\\ & = \frac{e^{-t}}{(e^t-1)\big(1-(1-e^{-t})(\alpha^2+(1-\alpha)^2)\big)} \leq \frac{1}{e^t-1},
\end{split}
\end{equation}
where both inequalities follow from the convexity of $x\mapsto x^2$.

\label{prop:ident}
Fix $n\in\mathbb{N}$, $\pmb{\alpha}=(\alpha_1,\ldots,\alpha_n)\in(0,1)^n$, $t\geq0$ and $\theta_1,\ldots,\theta_n\in\mathbb{R}$. Then, for every function $f:\{-1,1\}^n\to X$, where $X$ is a vector space, we have
\begin{equation} \label{eq:identi}
\forall \ x\in\{-1,1\}^n,\qquad \mathscr{L}_{\pmb{\alpha}} P_t^{\pmb{\alpha}} f(x) = - \mathbb{E}\Big[ \sum_{i=1}^n \eta_t^{\alpha_i}\big(x(i),X_t^{\pmb{\alpha}}(i);\theta_i\big) \partial_i^{\alpha_i} f(X_t^{\pmb{\alpha}}) \ \Big| \ X_0^{\pmb{\alpha}}=x\Big].
\end{equation}

In view of \eqref{eq:gen} and the product structure of the process $\{X_t^{\pmb{\alpha}}\}_{t\geq0}$, it suffices to check the claim for $n=1$, namely that for every $\beta\in(0,1)$, $\theta\in\mathbb{R}$ and $f:\{-1,1\}\to X$,
\begin{equation}
\forall \ x\in\{-1,1\},\qquad e^{-t} \partial^\beta f(x) = P_t^\beta \partial^\beta f(x) = \mathbb{E}\big[ \eta_t^\beta(x,X_t^\beta;\theta) \partial^\beta f(X_t^\beta) \ \big| \ X_0^\beta=x\big],
\end{equation}
where the first equality follows from the probabilistic representation \eqref{eq:sgp2}. Taking into account that $\beta \partial^\beta f(1) + (1-\beta) \partial^\beta f(-1) = 0$,  this amounts to the system of equations
\begin{equation}
\begin{cases}
e^{-t} = p_t^\beta(1,1) \eta_t^\beta(1,1;\theta) - \frac{\beta}{1-\beta} p_t^\beta(1,-1) \eta_t^\beta(1,-1;\theta) \\
e^{-t} = -\frac{1-\beta}{\beta} p_t^\beta(-1,1) \eta_t^\beta(-1,1;\theta) + p_t^\beta(-1,-1) \eta_t^\beta(-1,-1;\theta)
\end{cases}
\end{equation}
which can be easily verified by direct computation.

\label{thm:poincare}
Fix $p\in[1,2]$ and let $(X,\|\cdot\|_X)$ be a normed space of Rademacher type $p$.  Then, for any $n\in\mathbb{N}$ and $\pmb{\alpha}=(\alpha_1,\ldots,
\alpha_n)\in(0,1)^n$, every function $f:\{-1,1\}^n\to X$ satisfies
\begin{equation}
\int_{\{-1,1\}^n}\Big\| f(x) - \int_{\{-1,1\}^n} f \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}} \Big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x) \leq \big(2\pi \mathsf{T}_p(X)\big)^p \sum_{i=1}^n \int_{\{-1,1\}^n} \big\| \partial_i^{\alpha_i} f(x)\big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x).
\end{equation}

Writing
\begin{equation}
f(x) - \int_{\{-1,1\}^n} f \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}} = P_0^{\pmb{\alpha}}f(x) - P_\infty^{\pmb{\alpha}}f(x) = - \int_0^\infty \mathscr{L}_{\pmb{\alpha}} P_t^{\pmb{\alpha}}f(x)\,\mathop{}\!\mathrm{d} t
\end{equation}
and using Jensen's inequality and Proposition \ref{prop:ident}, we see that for $\theta_1(t),\ldots,\theta_n(t)\in\mathbb{R}$,
\begin{equation} \label{eq:apply-sgp}
\begin{split}
\Bigg(\int_{\{-1,1\}^n}\Big\| &f(x)  - \int_{\{-1,1\}^n} f \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}} \Big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x) \Bigg)^{1/p}\leq \int_0^\infty \Bigg(\int_{\{-1,1\}^n}\Big\|  \mathscr{L}_{\pmb{\alpha}} P_t^{\pmb{\alpha}}f(x) \Big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)\Bigg)^{1/p} \,\mathop{}\!\mathrm{d} t
\\ & = \int_0^\infty \Bigg(\int_{\{-1,1\}^n}\Bigg\| \mathbb{E}\Big[ \sum_{i=1}^n \eta_t^{\alpha_i}\big(x(i),X_t^{\pmb{\alpha}}(i);\theta_i(t)\big) \partial_i^{\alpha_i} f(X_t^{\pmb{\alpha}}) \ \Big| \ X_0^{\pmb{\alpha}}=x\Big] \Bigg\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)\Bigg)^{1/p} \,\mathop{}\!\mathrm{d} t
\\ & \leq \int_0^\infty \Bigg( \mathbb{E} \Big\| \sum_{i=1}^n \eta_t^{\alpha_i}\big(X_0^{\pmb{\alpha}}(i),X_t^{\pmb{\alpha}}(i);\theta_i(t)\big) \partial_i^{\alpha_i} f(X_t^{\pmb{\alpha}}) \Big\|_X^p \Bigg)^{1/p} \, \mathop{}\!\mathrm{d} t,
\end{split}
\end{equation}
where in the last expectation $X_0^{\pmb{\alpha}}$ is distributed according to $\mu_{\pmb{\alpha}}$. Now, by the reversibility of the chain, this expectation can be written as
\begin{equation} \label{eq:use-rev}
\begin{split}
\mathbb{E} \Big\| \sum_{i=1}^n \eta_t^{\alpha_i}\big(X_0^{\pmb{\alpha}}(i),X_t^{\pmb{\alpha}}(i);&\theta_i(t)\big)  \partial_i^{\alpha_i} f(X_t^{\pmb{\alpha}}) \Big\|_X^p 
\\ & = \int_{\{-1,1\}^n} \sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \eta_t^{\alpha_i}\big(y(i),x(i);\theta_i(t)\big) \partial_i^{\alpha_i} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x).
\end{split}
\end{equation}
Fixing $x\in\{-1,1\}^n$,  equation \eqref{eq:center} asserts that each $\eta_t^{\alpha_i} (y(i),x(i);\theta_i(t))$ is a centered random variable when $y(i)$ is distributed according to $p_t^{\alpha_i}(x(i),\cdot)$. Therefore,  as $p_t^{\pmb{\alpha}}(x,\cdot)$ is a product measure,  the Rademacher type condition for sums of centered independent random vectors (see \cite[Proposition~9.11]{LT91}) yields the bound
\begin{equation} \label{eq:use-type}
\begin{split}
& \int_{\{-1,1\}^n} \sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \eta_t^{\alpha_i}\big(y(i),x(i);\theta_i(t)\big) \partial_i^{\alpha_i} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)
\\ & \leq \big( 2\mathsf{T}_p(X)\big)^p \int_{\{-1,1\}^n} \sum_{i=1}^n \sum_{y(i)\in \{-1,1\}} p_t^{\alpha_i}\big(x(i),y(i)\big)\ \big|\eta_t^{\alpha_i}\big(y(i),x(i);\theta_i(t)\big)\big|^p \big\|\partial_i^{\alpha_i} f(x)\big\|_X^p \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)
\\ & \leq \big( 2\mathsf{T}_p(X)\big)^p  \sum_{i=1}^n \int_{\{-1,1\}^n} \Big(\sum_{y(i)\in \{-1,1\}} p_t^{\alpha_i}\big(x(i),y(i)\big)\ \big|\eta_t^{\alpha_i}\big(y(i),x(i);\theta_i(t)\big)\big|^2\Big)^{p/2} \big\|\partial_i^{\alpha_i} f(x)\big\|_X^p \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x),
\end{split}
\end{equation}
where we also used that $p\leq2$.  Now, choosing the $\theta_i(t)$ which minimize the quantity in the left-hand side of \eqref{eq:second-mom} with bias $\alpha_i$,  and combining \eqref{eq:apply-sgp}, \eqref{eq:use-rev} and \eqref{eq:use-type}, we conclude that
\begin{equation}
\begin{split}
 \Bigg(\int_{\{-1,1\}^n}\Big\| f(x)  - & \int_{\{-1,1\}^n} f \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}} \Big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x) \Bigg)^{1/p}
\\ & \leq 2\mathsf{T}_p(X) \int_0^\infty  \Bigg( \sum_{i=1}^n \int_{\{-1,1\}^n} \big\| \partial_i^{\alpha_i} f(x)\big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)   \Bigg)^{1/p} \, \frac{\mathop{}\!\mathrm{d} t}{\sqrt{e^t-1}},
\end{split}
\end{equation}
which is precisely the desired estimate.

Let $X=(\mathbb{R}^d,\|\cdot\|_X)$ be a $d$-dimensional normed space and suppose that $f:\{-1,1\}^n\to X$ is a function such that
\begin{equation} \label{eq:lip-con}
\forall \ x,y\in\{-1,1\}^n, \qquad \rho(x,y) \leq \|f(x)-f(y)\|_X \leq D\rho(x,y)
\end{equation}
for some $D\geq1$.  The conclusion of the theorem follows from \cite{IVV20} when $d\geq n$ so we shall assume that $d<n$.  Let $F:[-1,1]^n\to X$ be the multilinear extension of $f$ given by \eqref{eq:extension}. Then, $F$ is clearly continuous as a polynomial and therefore, by Lemma \ref{lem:ole2},  there exists a point $z\in\mathscr{C}_d^n$ such that $F(z)=F(-z)$.  As $z$ has at least $n-d$ coordinates equal to 1 in absolute value we shall assume without loss of generality that $|z({d+1})|=\ldots=|z(n)|=1$ and consider the functions $h_+, h_-:\{-1,1\}^d\to X$ which are defined as
\begin{equation}
\forall \ x\in\{-1,1\}^d, \qquad h_\pm(x) = f\big( \pm x(1),\ldots, \pm x(d),\pm z(d+1),\ldots,\pm z(n)\big).
\end{equation}
Consider also the bias vector $\pmb{\alpha}_z = \big( \frac{1+z(1)}{2},\ldots,\frac{1+z(d)}{2}\big)\in(0,1)^d$ and notice that, by the multilinearity of $F$, we have the identity
\begin{equation}
\int_{\{-1,1\}^d} h_+(x)\,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}_z}(x) = F(z) = F(-z) = \int_{\{-1,1\}^d} h_-(x)\,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}_z}(x).
\end{equation}
Therefore,  by the triangle inequality and Theorem \ref{thm:poincare} we get
\begin{equation} \label{eq:main-ineq}
\begin{split}
\int_{\{-1,1\}^d}\big\|  h_+(x) & - h_-(x) \big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}_z}(x)
\\ & \leq 2^{p-1} \int_{\{-1,1\}^d}\big\| h_+(x) - F(z) \big\|_X^p + \big\| h_-(x) - F(-z) \big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}_z}(x)
\\ & \leq 2^{2p-1} \big(\pi \mathsf{T}_p(X)\big)^p \sum_{i=1}^d \int_{\{-1,1\}^d} \big\| \partial_i^{\frac{1+z(i)}{2}} h_+(x)\big\|_X^p+\big\| \partial_i^{\frac{1+z(i)}{2}} h_-(x)\big\|_X^p \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}_z}(x)  .
\end{split}
\end{equation}
Now, in view of the lower Lipschitz condition \eqref{eq:lip-con}, we clearly have
\begin{equation*}
\big\|  h_+(x) - h_-(x) \big\|_X = \big\|  f\big(x(1),\ldots,x(d),z(d+1),\ldots,z(n)\big) - f\big(-x(1),\ldots,-x(d),-z(d+1),\ldots,-z(n)\big) \big\|_X \geq n
\end{equation*}
for every $x\in\{-1,1\}^d$. On the other hand, for a fixed $i\in\{1,\ldots,d\}$ and $\beta = \frac{1+z(i)}{2}$, we have
\begin{equation*}
\begin{split}
\int_{\{-1,1\}} \big\| \partial_i^\beta & h_+(x)\big\|_X^p\,\mathop{}\!\mathrm{d}\mu_\beta(x(i)) = \beta \|\partial_i^\beta h_+(x(1),\ldots,1,\ldots,x(d))\|_X^p + (1-\beta) \|\partial_i^\beta h_+(x(1),\ldots,-1,\ldots,x(d))\|_X^p
\\ & = \big( \beta(1-\beta)^p + (1-\beta) \beta^p \big) \ \big\|h_+(x(1),\ldots, 1,\ldots,x(d)) - h_+(x(1),\ldots, -1,\ldots,x(d))\big\|_X^p
\leq \frac{D^p}{2^p},
\end{split}
\end{equation*}
where in the last equality we used that $p\leq 2$ along with the upper Lipschitz condition \eqref{eq:lip-con}.  The same bound also holds for $h_-$.  Integrating the last two inequalities and combining them with \eqref{eq:main-ineq}, we deduce that
\begin{equation}
n^p \leq (2\pi \mathsf{T}_p(X))^p d D^p,
\end{equation}
which completes the proof of the theorem.

The identity of Proposition \ref{prop:ident} in the case of the uniform measure $\sigma_n$ (which was obtained in \cite{IVV20}) is simpler.  Let $\xi_1(t),\ldots,\xi_n(t)$ be i.i.d.~random variables distributed according to $\mu_{\beta(t)}$, where $\beta(t) = \frac{1+e^{-t}}{2}$. Then, for any point $x\in\{-1,1\}^n$,  the corresponding unbiased process $\{X_t(i)\}_{t\geq0}$ with $X_0=x$ has distribution equal to $x(i)\xi_i(t)$ at time $t$.  Thus applying formula \eqref{eq:identi} with $\alpha_i = \frac{1}{2}$ and $\theta_i (t)= \tfrac{e^{-t}}{2}$, we recover the usual identity
\begin{equation} \label{eq:ivv}
\forall \ x\in\{-1,1\}^n,\qquad \mathscr{L}P_t f(x) = - \mathbb{E}\Big[  \sum_{i=1}^n \frac{\xi_i(t)-e^{-t}}{e^t-e^{-t}}\cdot  \partial_i f\big(x\xi(t)\big) \Big],
\end{equation}
where $x\xi(t) = (x(1)\xi_1(t),\ldots,x(n)\xi_n(t))$, as was proven in \cite{IVV20}.

\label{thm:pisier-weak}
For every $\alpha\in(0,1)$, there exists $\mathsf{K}_{\alpha}\in(0,\infty)$ such that the following holds when $p\in[1,\infty)$.  For any normed space $(X,\|\cdot\|_X)$ and any $n\in\mathbb{N}$,  every function $f:\{-1,1\}^n\to X$ satisfies
\begin{equation} \label{eq:pw1}
\bigg\| f - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\mu_\alpha^n\bigg\|_{L_p(\mu_\alpha^n;X)} \leq \mathsf{K}_{\alpha}(\log n+1) \left( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i^\alpha f\Big\|_{L_p(\mu_\alpha^n;X)}^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta)\right)^{1/p}.
\end{equation}
If additionally $X$ is assumed to be of finite cotype, then there exists $\mathsf{K}_{p,\alpha}(X)$ such that
\begin{equation} \label{eq:pw2}
\bigg\| f - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\mu_\alpha^n\bigg\|_{L_p(\mu_\alpha^n;X)} \leq \mathsf{K}_{p,\alpha}(X)  \left( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i^\alpha f\Big\|_{L_p(\mu_\alpha^n;X)}^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta)\right)^{1/p}.
\end{equation}

Let $\pmb{\alpha}=(\alpha,\ldots,\alpha)$ and without loss of generality assume that $\int f \,\mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}=0$.  We start by proving the general inequality \eqref{eq:pw1}.  Notice that, by convexity, 
\begin{equation}
\big\| \mathscr{L}_{\pmb{\alpha}}f\big\|_{L_p(\mu_{\pmb{\alpha}};X)} \stackrel{\eqref{eq:gen}}{\leq} \sum_{i=1}^n \big\| \partial_i^\alpha f\big\|_{L_p(\mu_{\pmb{\alpha}};X)} \leq 2n \| f \|_{L_p(\mu_{\pmb{\alpha}};X)},
\end{equation}
where the last inequality follows from the definitions of $\partial_i^\alpha$. Therefore, 
\begin{equation*}
\begin{split}
\forall \ t\geq0,  \qquad \big\| e^{-t\mathscr{L}_{\pmb{\alpha}}} f\big\|_{L_p(\mu_{\pmb{\alpha}};X)} \leq \sum_{m=0}^\infty \frac{t^m}{m!} \big\| \mathscr{L}_{\pmb{\alpha}}^mf\big\|_{L_p(\mu_{\pmb{\alpha}};X)} \leq\sum_{m=0}^\infty \frac{(2nt)^m}{m!} \|f\|_{L_p(\mu_{\pmb{\alpha}};X)} = e^{2nt}\|f\|_{L_p(\mu_{\pmb{\alpha}};X)}.
\end{split}
\end{equation*}
Since $P_t^{\pmb{\alpha}} = e^{t\mathscr{L}_{\pmb{\alpha}}}$ for $t\geq0$,  this inequality applied to $P_t^{\pmb{\alpha}}f$ with $t=\tfrac{1}{n}$ implies that
\begin{equation}
\|f\|_{L_p(\mu_{\pmb{\alpha}};X)} \leq e^2 \big\|P_{1/n}^{\pmb{\alpha}}f\big\|_{L_p(\mu_{\pmb{\alpha}};X)}.
\end{equation}
Similarly to \eqref{eq:apply-sgp} and \eqref{eq:use-rev}, we thus have
\begin{equation}
\begin{split}
\|f&\|_{L_p(\mu_{\pmb{\alpha}};X)}\leq e^2 \big\|P_{1/n}^{\pmb{\alpha}}f\big\|_{L_p(\mu_{\pmb{\alpha}};X)}.
\\ & \leq
e^2 \int_{1/n}^\infty \left( \int_{\{-1,1\}^n} \sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \eta_t^{\alpha}\big(y(i),x(i);\theta_i(t)\big) \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)\right)^{1/p} \,\mathop{}\!\mathrm{d} t
\end{split}
\end{equation}
Fix $t\geq0$ and $x\in\{-1,1\}^n$.  Since $p_t^{\pmb{\alpha}}(x,\cdot)$ is a product measure,  the centering condition \eqref{eq:center} gives
\begin{equation} \label{use-cent}
\begin{split}
\sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) & \Big\| \sum_{i=1}^n \eta_t^{\alpha}\big(y(i),x(i);\theta_i(t)\big) \partial_i^{\alpha} f(x)\Big\|_X^p
\\ & \leq 2^p \int_{\{-1,1\}^n} \sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \delta_i \big| \eta_t^{\alpha}\big(y(i),x(i);\theta_i(t)\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(\delta).
\end{split}
\end{equation}
To prove \eqref{eq:pw1}, set $\theta_i(t) = \frac{e^{-t}}{2}$ and observe that by the contraction principle \cite[Theorem~4.4]{LT91}, we can further bound this quantity by
\begin{equation}
\begin{split}
2^p \sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) & \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \big| \eta_t^{\alpha}\big(y(i),x(i);\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(\delta)
\\& \leq 2^p \max_{\chi,\psi\in\{-1,1\}} \big| \eta_t^{\alpha}\big(\psi,\chi;\tfrac{e^{-t}}{2}\big)\big|^p \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(\delta).
\end{split}
\end{equation}
It is now elementary to check that we have 
\begin{equation}
\max_{\chi,\psi\in\{-1,1\}}\big|\eta_t^{\alpha}\big(\psi,\chi;\tfrac{e^{-t}}{2}\big)\big| \lesssim_\alpha \begin{cases} \frac{1}{t}, & \mbox{for }t\in(0,1) \\ e^{-t}, & \mbox{for } t\geq1 \end{cases}
\end{equation}
and thus combining all the above we get
\begin{equation}
\|f\|_{L_p(\mu_{\pmb{\alpha}};X)} \lesssim_{\alpha} \left( \int_{1/n}^1 \frac{\mathop{}\!\mathrm{d} t}{t} + \int_1^\infty e^{-t}\,\mathop{}\!\mathrm{d} t \right)\cdot\left( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i f\Big\|_{L_p(\mu_{\pmb{\alpha}};X)}^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta)\right)^{1/p},
\end{equation}
which readily concludes the proof of \eqref{eq:pw1}.

For the proof of \eqref{eq:pw2},  we combine \eqref{eq:apply-sgp} and \eqref{eq:use-rev} with \eqref{use-cent} to get
\begin{equation*}
\|f\|_{L_p(\mu_{\pmb{\alpha}};X)}\leq
2 \int_{0}^\infty \left( \int_{\{-1,1\}^{2n}}\sum_{y\in \{-1,1\}^n} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \delta_i \big| \eta_t^{\alpha}\big(y(i),x(i);\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(\delta) \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}}(x)\right)^{1/p}\!\!\!\! \mathop{}\!\mathrm{d} t.
\end{equation*}
Fix $x\in\{-1,1\}^n$ and $t\geq0$.  Denoting by $I(x)= \{i:\  x(i)=1\}$,  the inner term is bounded above by
\begin{equation} \label{eq:break-to-iid}
\begin{split}
 \int_{\{-1,1\}^n} & \sum_{y\in \{-1,1\}^n}  p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i=1}^n \delta_i \big| \eta_t^{\alpha}\big(y(i),x(i);\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(\delta)
\\ & \leq 2^{p-1} \int_{\{-1,1\}^{I(x)}} \sum_{y\in \{-1,1\}^{I(x)}} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i\in I(x)} \delta_i \big| \eta_t^{\alpha}\big(y(i),1;\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_{I(x)}(\delta)
\\ & + 2^{p-1}  \int_{\{-1,1\}^{I(x)^c}}  \sum_{y\in \{-1,1\}^{I(x)^c}} p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i\notin I(x)} \delta_i \big| \eta_t^{\alpha}\big(y(i),-1;\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p\, \mathop{}\!\mathrm{d}\sigma_{I(x)^c}(\delta).
\end{split}
\end{equation}
When $y\in\{-1,1\}^{I(x)}$ is distributed according to $p_t^{\pmb{\alpha}}(x,\cdot)$ and $\delta$ is a uniformly random sign, the random variables $\delta_i|\eta_t^{\alpha}(y(i),1;\tfrac{e^{-t}}{2})|$,  $i\in I(x)$, are independent and identically distributed.  Therefore, standard comparison principles going back to works of Maurey and Pisier (see, e.g., \cite[Proposition~9.14]{LT91}) show that if $X$ has cotype $q<\infty$ and $r> \max\{p, q\}$, then
\begin{equation} \label{eq:Ix}
\begin{split}
\int_{\{-1,1\}^{I(x)}} &\sum_{y\in \{-1,1\}^{I(x)}}  p_t^{\pmb{\alpha}}(x,y) \Big\| \sum_{i\in I(x)} \delta_i \big| \eta_t^{\alpha}\big(y(i),1;\tfrac{e^{-t}}{2}\big)\big| \partial_i^{\alpha} f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_{I(x)}(\delta)
\\ & \lesssim_{r,X}  \Big( \sum_{\psi\in\{-1,1\}}p_t^{{\alpha}} \big(1,\psi;\tfrac{e^{-t}}{2}\big) \big| \eta_t^{\alpha}\big(\psi,1;\tfrac{e^{-t}}{2}\big)\big|^r \Big)^{p/r} \int_{\{-1,1\}^{I(x)}}  \Big\| \sum_{i\in I(x)} \delta_i \partial_i^{\alpha} f(x)\Big\|_X^p\, \mathop{}\!\mathrm{d}\sigma_{I(x)}(\delta).
\end{split}
\end{equation}
It is again elementary to show that
\begin{equation} \label{rmom}
\max_{\chi\in\{-1,1\}} \Big( \sum_{\psi\in\{-1,1\}}p_t^{{\alpha}} \big(\chi,\psi;\tfrac{e^{-t}}{2}\big) \big| \eta_t^{\alpha}\big(\psi,\chi;\tfrac{e^{-t}}{2}\big)\big|^r \Big)^{1/r} \lesssim_{r,\alpha} \begin{cases} \frac{1}{t^{1-\frac1r}}, & \mbox{for }t\in(0,1) \\ e^{-t}, & \mbox{for } t\geq1 \end{cases}.
\end{equation}
In view of the convergence of the integrals
\begin{equation}
 \int_0^1 \frac{\mathop{}\!\mathrm{d} t}{t^{1-\frac1r}} + \int_1^\infty e^{-t}\,\mathop{}\!\mathrm{d} t  \lesssim_r 1,
\end{equation}
combining \eqref{eq:Ix}, the corresponding estimate on $I(x)^c$ and \eqref{eq:break-to-iid}, we finally get
\begin{equation*}
\begin{split}
\|f\|_{L_p(\mu_{\pmb{\alpha}};X)} \lesssim_{r,\alpha,X}   \left(\int_{\{-1,1\}^n} \int_{\{-1,1\}^n} \Big\| \sum_{i\in I(x)} \delta_i\partial_i^{\alpha} f(x)\Big\|_X^p + \Big\| \sum_{i\notin I(x)} \delta_i  \partial_i^{\alpha} f(x)\Big\|_X^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta) \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}(x)} \right)^{1/p}.
\end{split}
\end{equation*}
Now, if $F,G$ are two independent centered $X$-valued random vectors, then
\begin{equation}
\mathbb{E}\|F+G\|_X^p \geq \max\big\{ \mathbb{E}_F \|F+\mathbb{E}_G[G]\|_X^p, \mathbb{E}_G\|\mathbb{E}_F[F]+G\|_X^p\big\} = \max\big\{ \mathbb{E}\|F\|_X^p, \mathbb{E}\|G\|_X^p\big\}.
\end{equation}
Therefore, 
\begin{equation}
\begin{split}
  \Bigg(\int_{\{-1,1\}^n} \int_{\{-1,1\}^n} \Big\| \sum_{i\in I(x)} \delta_i\partial_i^{\alpha} f(x)\Big\|_X^p  + \Big\| \sum_{i\notin I(x)} & \delta_i  \partial_i^{\alpha} f(x)\Big\|_X^p \,\mathop{}\!\mathrm{d}\sigma_n(\delta) \, \mathop{}\!\mathrm{d}\mu_{\pmb{\alpha}(x)} \Bigg)^{1/p}
\\ & \lesssim  \left(\int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i\partial_i^{\alpha} f(x)\Big\|_{L_p(\mu_{\pmb{\alpha}};X)}^p  \,\mathop{}\!\mathrm{d}\sigma_n(\delta) \right)^{1/p}
\end{split}
\end{equation}
and this concludes the proof of the theorem.

Given a scalar-valued function $h:\{-1,1\}^n\to\mathbb{R}$, we denote by $\mathsf{M}h:\{-1,1\}^n\to\mathbb{R}_+$ the asymmetric gradient of $h$, given by
\begin{equation}
\forall \ x\in\{-1,1\}^n,\qquad \mathsf{M}h(x) = \bigg( \sum_{i=1}^n \partial_ih(x)_+^2\bigg)^{1/2},
\end{equation}
where $a_+=\max\{a,0\}$ for $a\in\mathbb{R}$.  A combination of the triangle inequality with a technical result of Talagrand \cite[Proposition~5.1]{Tal93} on the biased cube implies that if a vector-valued function $f:\{-1,1\}^n\to X$ satisfies $\int f \,\mathop{}\!\mathrm{d}\mu_\alpha^n=0$, then
\begin{equation}
\|f\|_{L_p(\log L)^{p/2}(\mu_\alpha^n;X)} \lesssim_{p,\alpha} \big\| \mathsf{M} \|f\|_X \big\|_{L_p(\mu_\alpha^n;X)} + \|f\|_{L_1(\mu_\alpha^n;X)}.
\end{equation}
The second term can be controlled by the right hand side of \eqref{eq:p1} or \eqref{eq:p2} using the results of Theorem \ref{thm:pisier-weak}.
 For the first term, we use the key pointwise inequality of \cite{CE24}, asserting that
 \begin{equation}
 \forall \ x\in\{-1,1\}^n,\qquad \mathsf{M}\|f\|_X(x) \leq \sqrt{2}\Bigg( \int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n \delta_i \partial_i f(x)\Big\|_X^p\, \mathop{}\!\mathrm{d}\sigma_n(\delta) \Bigg)^{1/p}.
 \end{equation}
To further upper bound this by the square function where $\partial_i$ is replaced by $\partial_i^\alpha$, observe that
\begin{equation}
\partial_i^\alpha f(x) \in\big\{ 2\alpha \partial_i f(x),  2(1-\alpha) \partial_if(x)\big\}
\end{equation}
and thus the contraction principle and integration in $x$ yield the desired conclusions.

\label{lem:lt}
A Banach space $(X,\|\cdot\|_X)$ has stable type $p\in[1,2)$ if and only if there exists a constant $\mathsf{ST}_p(X)\in(0,\infty)$ such that for every $n\in\mathbb{N}$ and every vectors $v_1,\ldots,v_n\in X$, we have
\begin{equation}  \label{eq:lt}
\int_{\{-1,1\}^n} \Big\| \sum_{i=1}^n x_i v_i\Big\|_X^p \,\mathop{}\!\mathrm{d}\sigma_n(x) \leq \mathsf{ST}_p(X)^p \big\|\big(\|v_1\|_X,\ldots,\|v_n\|_X\big)\big\|_{\ell_{p,\infty}^n}^p.
\end{equation}

It is clear from Lemma \ref{lem:lt} that any normed space with metric stable type $p$ also has stable type $p$.  For the converse implication,  we treat the case $p=1$ separately.  Assuming that $X$ has stable type 1,  it follows from \cite{Pis74b} that it also has nontrivial Rademacher type and thus (in view of \cite{Pis73}) finite cotype.  Therefore, by the $X$-valued Pisier inequality with a dimension-free constant of \cite{IVV20}, we get
\begin{equation}
\begin{split}
\int_{\{-1,1\}^n} \big\|f(x)-f(-x)\big\|_X\,\mathop{}\!\mathrm{d}\sigma_n(x) & \leq 2\int_{\{-1,1\}^n} \Big\| f(x) - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\sigma_n\Big\|_X \,\mathop{}\!\mathrm{d}\sigma_n(x)
\\ & \lesssim_{X}  \int_{\{-1,1\}^{n}}\int_{\{-1,1\}^{n}} \mathbb{E} \Big\|\sum_{i=1}^{n} \delta_i \partial_i f(x)\Big\|_X \, \mathop{}\!\mathrm{d}\sigma_n(\delta) \mathop{}\!\mathrm{d}\sigma_{n}(x).
\end{split}
\end{equation}
Applying Lemma \ref{lem:lt} conditionally on $x\in\{-1,1\}^n$, we can further bound this quantity as
\begin{equation}
\begin{split}
 \int_{\{-1,1\}^{n}}\int_{\{-1,1\}^{n}} \mathbb{E} \Big\|\sum_{i=1}^{n} & \delta_i \partial_i f(x)\Big\|_X \,  \mathop{}\!\mathrm{d}\sigma_n(\delta) \mathop{}\!\mathrm{d}\sigma_{n}(x)
\\ & \leq \mathsf{ST}_1(X)  \int_{\{-1,1\}^n} \big\|\big(\|\partial_1f(x)\|_X,\ldots,\|\partial_nf(x)\|_X\big)\big\|_{\ell_{1,\infty}^n} \, \mathop{}\!\mathrm{d}\sigma_n(x)
\end{split}
\end{equation}
and this proves the converse implication since $\mathfrak{d}_if(x) =  \|\partial_if(x)\|_X$.

While this proof extends to all values of $p$,  in the case $p>1$ we present a more cumbersome argument which avoids the $X$-valued Pisier inequality and thus gives better dependence on parameters of $X$.  For $t\geq0$,  let $\xi_1(t),\ldots,\xi_n(t)$ be i.i.d.~random variables distributed according to $\mu_{\beta(t)}$, where $\beta(t)=\tfrac{1+e^{-t}}{2}$,  and denote by $\eta_i(t) = \frac{\xi_i(t)-e^{-t}}{e^t-e^{-t}}$.  Then,  it follows from the semigroup argument leading to \eqref{eq:apply-sgp} along with identity \eqref{eq:ivv} of \cite{IVV20} and Jensen's inequality that
\begin{equation}
\begin{split}
\Bigg(\int_{\{-1,1\}^n} \big\|f(x)-f(-x)\big\|_X^p\,\mathop{}\!\mathrm{d}\sigma_n(x)\Bigg)^{1/p} & \leq 2\Bigg(\int_{\{-1,1\}^n} \Big\| f(x) - \int_{\{-1,1\}^n} f\,\mathop{}\!\mathrm{d}\sigma_n\Big\|_X^p \,\mathop{}\!\mathrm{d}\sigma_n(x)\Bigg)^{1/p}
\\ & \leq 2 \int_0^\infty \Bigg( \int_{\{-1,1\}^n} \mathbb{E} \Big\|\sum_{i=1}^n \eta_i(t) \partial_i f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(x)\Bigg)^{1/p} \,\mathop{}\!\mathrm{d} t
\end{split}
\end{equation}

Fixing $x\in\{-1,1\}^n$,  the independent random vectors $\eta_1(t)\partial_1f(x),\ldots,\eta_n(t)\partial_nf(x)$ are centered.  Thus, by standard symmetrization estimates, we can further bound the last term by
\begin{equation}
\begin{split}
2 \int_0^\infty \Bigg( \int_{\{-1,1\}^n} \mathbb{E} \Big\|\sum_{i=1}^n \eta_i(t) \partial_i f(x)\Big\|_X^p& \, \mathop{}\!\mathrm{d}\sigma_n(x)\Bigg)^{1/p} \,\mathop{}\!\mathrm{d} t
\\ & \leq 4 \int_0^\infty \Bigg( \int_{\{-1,1\}^n} \mathbb{E} \Big\|\sum_{i=1}^n \delta_i \eta_i(t) \partial_i f(x)\Big\|_X^p \, \mathop{}\!\mathrm{d}\sigma_n(x)\Bigg)^{1/p} \,\mathop{}\!\mathrm{d} t,
\end{split}
\end{equation}
where the  expectation on the right hand side is with respect to $(\delta_i,\eta_i(t))$, where the $\delta_i$ are uniformly random signs, independent of the $\eta_i(t)$. Therefore, conditioning first on the values of $\eta_1(t),\ldots,\eta_n(t)$ and using Lemma \ref{lem:lt} for the integrand, we get
\begin{equation}
 \mathbb{E} \Big\|\sum_{i=1}^n \delta_i\eta_i(t) \partial_i f(x)\Big\|_X^p \leq \mathsf{ST}_p(X)^p \mathbb{E} \bigg\|\sum_{i=1}^n \eta_i(t) \big\| \partial_if(x)\big\|_X e_i \bigg\|_{\ell_{p,\infty}^n}^p,
\end{equation}
where $\{e_1,\ldots,e_n\}$ is the standard basis of $\mathbb{R}^n$. It is well-known that, since $p>1$,  $\ell_{p,\infty}^n$ is isomorphic to a normed space up to constants depending only on $p$. Moreover,  it has finite cotype with a constant independent of $n$ (for instance because it can be realized as a real interpolation space between $\ell_1^n$ and $\ell_2^n$, see \cite[Section~5.3]{BL76}).  Therefore,  using again the comparison principle \cite[Proposition~9.14]{LT91}, we have
\begin{equation}
\begin{split}
\mathbb{E} \bigg\|\sum_{i=1}^n \eta_i(t) \big\| \partial_if(x)\big\|_X e_i \bigg\|_{\ell_{p,\infty}^n}^p&  \lesssim_{p} \|\eta_1(t)\|_{L_r}^p \mathbb{E} \bigg\|\sum_{i=1}^n \delta_i \big\| \partial_if(x)\big\|_X e_i \bigg\|_{\ell_{p,\infty}^n}^p 
\\ & =  \|\eta_1(t)\|_{L_r}^p \big\|\big(\|\partial_1f(x)\|_X,\ldots,\|\partial_nf(x)\|_X\big)\big\|_{\ell_{p,\infty}^n}^p
\end{split}
\end{equation}
for any $r>\max\{r',p\}$, where $r'$ is the cotype of $\ell_{p,\infty}^n$.  Combining all the above along with the fact that $t\mapsto \|\eta_1(t)\|_{L_r}$ is integrable for any $r<\infty$,  we conclude the proof.  It is worth emphasizing that this proof shows additionally that the metric stable type constant of $X$ is proportional to the parameter $\mathsf{ST}_p(X)$ of \eqref{eq:lt} up to constants depending only on $p$, provided that $p>1$.

Suppose that $(\mathsf{M},d_\mathsf{M})$ has metric stable type $p$ with constant $S$ and suppose that a function $f:\{-1,1\}^n\to\mathsf{M}$ satisfies
\begin{equation} \label{xx}
\forall \ x,y\in\{-1,1\}^n,\qquad s \rho_{\bf w}(x,y) \leq d_\mathsf{M}\big(f(x),f(y)\big) \leq sD \rho_{\bf w}(x,y)
\end{equation} 
for some constants $s>0$ and $D\geq1$. Combined with the stable type assumption, this gives
\begin{equation}
\begin{split}
s^p \|{\bf w}\|_{\ell_1^n}^p  \stackrel{\eqref{xx}}{\leq} \int_{\{-1,1\}^n}  d_\mathsf{M}\big( f(x)&,f(-x)\big)^p \,\mathop{}\!\mathrm{d}\sigma_n(x) \leq S^p  \int_{\{-1,1\}^n} \big\| \big(\mathfrak{d}_1f(x),\ldots,\mathfrak{d}_nf(x)\big)\big\|^p_{\ell_{p,\infty}^n} \,\mathop{}\!\mathrm{d}\sigma_n(x)
\\ &\stackrel{\eqref{xx}}{\leq} (sSD)^p  \int_{\{-1,1\}^n} \| (w_1,\ldots,w_n)\|^p_{\ell_{p,\infty}^n} \,\mathop{}\!\mathrm{d}\sigma_n(x) = (sSD)^p \|{\bf w}\|_{\ell_{p,\infty}^n}^p.
\end{split}
\end{equation}
Rearranging gives the desired lower bound \eqref{eq:dist} for the distortion $D$.
